"tokyo|Cat Cafe MOCHA Lounge Shinjuku":{"t": "10 صباحًا–9 مساءً، آخر دخول 8:30", "cost": "¥270–350 لكل 10 دقائق", "dur": "30–60 دقيقة", "cap": "قطط ومشروب مجاني", "tip": "الحساب بكل عشر دقائق، ومشروبات الآلة مشمولة، وحلوى القطط ¥550 إذا أردت أن تصبح محبوبًا. دقيقتان من المخرج الجنوبي الشرقي لمحطة شينجوكو. لا يوجد حجز، فقط احضر."},
"tokyo|BAM BI COFFEE":{"t": "11 صباحًا–10:30 مساءً", "cost": "~¥1,500", "dur": "1 ساعة", "cap": "بان كيك كوري", "tip": "مقهى صغير على الطريقة الكورية يقدّم بان كيك سوفليه جميلًا جدًا في الصور، ولهذا بالضبط قد يتجاوز الانتظار ساعة في نهاية الأسبوع. يُغلق متأخرًا، فهو محطة مسائية جيدة بدلًا من ذلك."},
"tokyo|Final Fantasy Eorzea Cafe":{"t": "10:45 صباحًا–11 مساءً، فترات 90 دقيقة", "cost": "~¥2,000–3,500", "dur": "1.5 ساعة", "cap": "FF14 كما يجب", "tip": "مقهى FFXIV الرسمي في الطابق الثاني من Pasela Akiba، فيه أطباق مستوحاة من اللعبة وكثير من المنتجات التي لم تخطط لشرائها. فترات محددة مدتها 90 دقيقة، تُحجز أونلاين عند الظهر تمامًا قبل شهر كامل، والدخول بدون حجز فقط إذا كان هناك مقعد فاضي. الكحول موجود في قائمة المشروبات، فاطلب من قسم المشروبات الغازية والعصائر."},
"tokyo|Morinoen":{"t": "المتجر 9–7، والمقهى 12–6 مساءً", "cost": "~¥500–1,000", "dur": "40 دقيقة", "cap": "آيس كريم هوجيتشا", "tip": "متخصص في شاي الهوجيتشا منذ 1914، ويحمّص شايه في المكان نفسه، فتشمّ رائحة المتجر قبل أن تراه. ثلاثون ثانية من مخرج A1 في نينغيوتشو. خذ الآيس كريم الطري بالشاي المحمّص في الطابق السفلي حتى لو تخطّيت المقهى."},
"tokyo|Owl Nest Cafe":{"t": "أيام الأسبوع 1–7 مساءً، ونهاية الأسبوع 12–8 مساءً", "cost": "~¥1,000 للساعة مع مشروب", "dur": "1 ساعة", "cap": "بومة على كتفك", "tip": "ساعة مع البوم، مع مشروب واحد، و¥500 إضافية إذا أردت إطعامها. المراجعون يقولون دائمًا إن الطيور هنا تبدو بحالة جيدة وحرّة في الطيران، لكن مقاهي البوم موضوع مثير للجدل، فاذهب وأنت واعٍ بذلك أو تخطَّه."},
"tokyo|Hekkelun":{"t": "9 صباحًا–3 مساءً، الاثنين/الثلاثاء/الخميس/الجمعة فقط", "cost": "~¥900", "dur": "40 دقيقة", "cap": "اثنا عشر بودينغ يوميًا", "tip": "كيساتين قديم من عصر شووا، صاحبه يصنع اثني عشر بودينغ كراميل بالضبط كل يوم. الطابور يبدأ حوالي 8 صباحًا وتنفد قبل الظهر، فهذه خطة لمن يصحو مبكرًا. مغلق الأربعاء والسبت والأحد، والتدخين مسموح في الداخل."},
"tokyo|Sarabeth's Shinjuku":{"t": "9 صباحًا–10 مساءً", "cost": "~¥2,000–2,800", "dur": "1 ساعة", "cap": "بان كيك ليمون وريكوتا", "tip": "مطعم البرانش النيويوركي، في الطابق الثاني من Lumine 2 فوق المخرج الجنوبي لمحطة شينجوكو مباشرة. بان كيك الليمون والريكوتا والبيض بنديكت هما سبب المجيء. صباحات نهاية الأسبوع فيها طوابير، فاذهب في يوم عادي أو آخر العصر."},
"tokyo|Ginza Chuo-dori":{"t": "العصر؛ بدون سيارات السبت والأحد", "cost": "المشي مجاني", "dur": "1–2 ساعة", "cap": "جنة المشاة", "tip": "الشارع الرئيسي في غينزا. عصر السبت والأحد يُغلقونه أمام السيارات ويضعون كراسي في وسط الطريق، وهذا هو الوقت المناسب للمشي فيه. التفرّج على الواجهات مجاني حتى لو لم يكن أي شيء آخر هنا مجانيًا."},
"tokyo|MEGA Don Quijote Shibuya":{"t": "مفتوح 24 ساعة", "cost": "—", "dur": "1 ساعة", "cap": "هدايا الساعة 3 فجرًا", "tip": "فرع Don Quijote الكبير في شيبويا، مفتوح على مدار الساعة، وأسهل مكان تنهي فيه قائمة الهدايا دفعة واحدة. كاونتر الإعفاء الضريبي في الطابق العلوي، فأحضر جوازك. تحقّق من مكونات الوجبات الخفيفة بحثًا عن جيلاتين الخنزير والميرين إذا كان هذا يهمك."},
"tokyo|Nakamise-dori":{"t": "المحلات ~9:30 صباحًا–6 مساءً", "cost": "المشي مجاني", "dur": "30–45 دقيقة", "cap": "الطريق إلى سينسو-جي", "tip": "شارع التسوق بطول 250 مترًا بين بوابة كاميناريمون ومعبد سينسو-جي، وهو موجود منذ القرن السابع عشر. نينغيو-ياكي وأغي-مانجو هما ما تأكله وأنت تمشي. تعال قبل العاشرة أو بعد الخامسة إلا إذا كنت تحب الزحمة."},
"tokyo|Pokemon Center Tokyo DX":{"t": "10:30 صباحًا–9 مساءً", "cost": "—", "dur": "45 دقيقة", "cap": "المتجر الرئيسي", "tip": "أكبر Pokémon Center في اليابان، في الطابق الخامس من Nihonbashi Takashimaya East. مقهى Pokémon Café في الطابق نفسه لكنه يحتاج حجزًا منفصلًا قبل شهر، أما المتجر فلا، فتستطيع الدخول حتى لو كان المقهى ممتلئًا."},
"tokyo|Sunshine City":{"t": "المحلات 10 صباحًا–8 مساءً", "cost": "الدخول مجاني؛ والأنشطة بسعر إضافي", "dur": "2–3 ساعة", "cap": "أكواريوم على السطح", "tip": "مجمّع كامل في مبنى واحد: محلات، وSunshine Aquarium على السطح، وقبة فلكية، وPokémon Center، وNamja Town. مفيد جدًا في يوم ممطر، تستطيع أن تقضي العصر كله هنا بدون أن تخرج."},
